export const lessonIndex = () => TRACKS.flatMap((track) => track.lessons.map((lesson) => ({ track: track.id, trackTitle: track.title, ...lesson })));
export const findLesson = (id) => lessonIndex().find((lesson) => lesson.id === id) ?? null;
